// One of the two packages. Its `Holder<T>.get` doubles the field where the root
// package's answers it unchanged, so a call that reached the wrong
// instantiation changes the exit code rather than quietly agreeing with it.
class Holder<T> {
  value: T;

  constructor(v: T) {
    this.value = v;
  }

  get(): T {
    return this.value + this.value;
  }
}

export const fromA = (): i32 => toI32(new Holder<i64>(toI64(7)).get());
